  1→'use client';
  2→
  3→// Auto-deploy test: GitHub → Vercel connected ✓
  4→
  5→import { useState, useEffect, useMemo } from 'react';
  6→import { HeroReel } from '@/components/HeroReel';
  7→import { LadderGrid } from '@/components/LadderGrid';
  8→import { usePerception } from '@/lib/perception/context';
  9→import { projects } from '@/lib/projects';
 10→import { ProjectAdapter } from '@/lib/perception/adapter';
 11→import { VisitorArchetype } from '@/lib/perception/types';
 12→
 13→export default function HomePage() {
 14→  // Get perception state from context (sensor runs in PerceptionLayer)
 15→  const { archetype, confidence } = usePerception();
 16→
 17→  const [scrollIndicatorOpacity, setScrollIndicatorOpacity] = useState(1);
 18→  const [introTextOpacity, setIntroTextOpacity] = useState(1);
 19→  const [mainContentTopOpacity, setMainContentTopOpacity] = useState(1);
 20→  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
 21→  const [introVisible, setIntroVisible] = useState(false);
 22→  const [isMobile, setIsMobile] = useState(false);
 23→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
 24→
 25→  // Detect mobile (touch device OR narrow viewport) and reduced motion preference
 26→  useEffect(() => {
 27→    const checkMobile = () => {
 28→      const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
 29→      const isNarrowViewport = window.innerWidth < 768;
 30→      setIsMobile(isTouchDevice || isNarrowViewport);
 31→    };
 32→    checkMobile();
 33→    window.addEventListener('resize', checkMobile);
 34→
 35→    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
 36→    setPrefersReducedMotion(motionQuery.matches);
 37→    const handleMotionChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
 38→    motionQuery.addEventListener('change', handleMotionChange);
 39→
 40→    return () => {
 41→      window.removeEventListener('resize', checkMobile);
 42→      motionQuery.removeEventListener('change', handleMotionChange);
 43→    };
 44→  }, []);
 45→
 46→  // Hero height based on device - matches HeroReel component
 47→  const heroHeight = isMobile ? '50vh' : '70vh';
 48→  const heroHeightMultiplier = isMobile ? 0.5 : 0.7;
 49→
 50→  // Trigger intro animation on mount
 51→  useEffect(() => {
 52→    const timer = setTimeout(() => setIntroVisible(true), 100);
 53→    return () => clearTimeout(timer);
 54→  }, []);
 55→
 56→  // Listen for chatbot open/close to hide scroll indicator
 57→  useEffect(() => {
 58→    const observer = new MutationObserver((mutations) => {
 59→      mutations.forEach((mutation) => {
 60→        if (mutation.type === 'attributes' && mutation.attributeName === 'data-chatbot-open') {
 61→          const isOpen = document.body.hasAttribute('data-chatbot-open');
 62→          setIsChatbotOpen(isOpen);
 63→        }
 64→      });
 65→    });
 66→
 67→    observer.observe(document.body, { attributes: true });
 68→    return () => observer.disconnect();
 69→  }, []);
 70→
 71→  // Fade out scroll indicator and intro text on scroll
 72→  useEffect(() => {
 73→    const handleScroll = () => {
 74→      const scrollY = window.scrollY;
 75→
 76→      // Fade out scroll indicator between 0-300px scroll
 77→      const scrollIndicatorOp = Math.max(0, 1 - (scrollY / 300));
 78→      setScrollIndicatorOpacity(scrollIndicatorOp);
 79→
 80→      // Fade out intro text ONLY right before it overlaps navigation
 81→      const fadeStart = 600;
 82→      const fadeEnd = 800;
 83→      const fadeRange = fadeEnd - fadeStart;
 84→
 85→      let introOp = 1;
 86→      if (scrollY > fadeStart) {
 87→        introOp = Math.max(0, 1 - ((scrollY - fadeStart) / fadeRange));
 88→      }
 89→      setIntroTextOpacity(introOp);
 90→
 91→      // Fade ALL content scrolling under navigation
 92→      const currentHeroHeight = window.innerHeight * heroHeightMultiplier;
 93→      const contentTopPosition = currentHeroHeight - scrollY;
 94→      const navHeight = 200;
 95→
 96→      let mainTopOp = 1;
 97→      if (contentTopPosition < navHeight) {
 98→        const fadeDistance = 150;
 99→        const distanceIntoNav = navHeight - contentTopPosition;
100→        mainTopOp = Math.max(0, 1 - (distanceIntoNav / fadeDistance));
101→      }
102→      setMainContentTopOpacity(mainTopOp);
103→    };
104→
105→    window.addEventListener('scroll', handleScroll, { passive: true });
106→    return () => window.removeEventListener('scroll', handleScroll);
107→  }, [heroHeightMultiplier]);
108→
109→  // Find General Reel for hero
110→  const heroProject = projects.find(p => p.slug === 'general-reel');
111→
112→  // Hero statement - authentic, consistent regardless of mode
113→  const heroStatement = "Sixteen years. Feature films, commercials, real-time engines—each frame a problem of light solved in pixels. This is the work.";
114→
115→  // Adapt project order based on visitor archetype
116→  // Only adapts when confidence > 0.5 to avoid premature/unstable reordering
117→  const adaptedProjects = useMemo(() => {
118→    const gridProjects = projects.filter(p => p.slug !== 'general-reel');
119→
120→    // Confidence threshold: don't adapt on weak signal
121→    if (confidence < 0.5 || !archetype) {
122→      return gridProjects;
123→    }
124→
125→    return ProjectAdapter.adaptProjectOrder(gridProjects, archetype);
126→  }, [archetype, confidence]);
127→
128→  return (
129→    <>
130→      {/* Hero Reel - Fixed position, crossfades on scroll, below navigation */}
131→      {heroProject && (
132→        <HeroReel
133→          videoId={heroProject.videoId}
134→          videoHash={heroProject.videoHash}
135→          startTime={heroProject.startTime}
136→          thumbnail={heroProject.thumbnail}
137→        />
138→      )}
139→
140→      {/* Scroll indicator - positioned right below hero reel, hidden when chatbot is open */}
141→      <div
142→        className="fixed left-0 right-0 flex flex-col items-center"
143→        style={{
144→          top: `calc(${heroHeight} - 60px)`,
145→          zIndex: 90,
146→          opacity: isChatbotOpen ? 0 : scrollIndicatorOpacity,
147→          pointerEvents: (isChatbotOpen || scrollIndicatorOpacity === 0) ? 'none' : 'auto',
148→          transition: 'opacity 0.3s ease-out'
149→        }}
150→      >
151→        <svg
152→          className="scroll-chevron"
153→          width="24"
154→          height="24"
155→          viewBox="0 0 24 24"
156→          fill="none"
157→          stroke="#8a8a8a"
158→          strokeWidth="2"
159→          strokeLinecap="round"
160→          strokeLinejoin="round"
161→        >
162→          <polyline points="6 9 12 15 18 9" />
163→        </svg>
164→        <p
165→          style={{
166→            color: '#8a8a8a',
167→            fontFamily: 'var(--font-display)',
168→            fontSize: '11px',
169→            fontWeight: 600,
170→            letterSpacing: '0.04em',
171→            textTransform: 'uppercase',
172→            marginTop: '8px'
173→          }}
174→        >
175→          Scroll
176→        </p>
177→      </div>
178→
179→      {/* Gradient fade overlay for content scrolling under navigation */}
180→      <div
181→        className="fixed top-0 left-0 right-0 pointer-events-none transition-opacity duration-400 ease-out"
182→        style={{
183→          height: '250px',
184→          background: 'linear-gradient(to bottom, #141414 0%, transparent 100%)',
185→          zIndex: 95,
186→          opacity: mainContentTopOpacity < 1 ? (1 - mainContentTopOpacity) * 0.95 : 0
187→        }}
188→      />
189→
190→      {/* Main content - starts below viewport, scrolls up */}
191→      <main className="min-h-screen relative" style={{ marginTop: heroHeight, zIndex: 50, backgroundColor: '#141414' }}>
192→        {/* Hero Statement - Isolated quote with generous whitespace (Pentagram style) */}
193→        <section
194→          className="mx-auto"
195→          style={{
196→            maxWidth: 'var(--max-content-width)',
197→            paddingLeft: 'var(--side-padding)',
198→            paddingRight: 'var(--side-padding)',
199→            paddingTop: 'clamp(102px, 10.2vw + 34px, 170px)',
200→            paddingBottom: 'clamp(102px, 10.2vw + 34px, 170px)',
201→            opacity: introTextOpacity
202→          }}
203→        >
204→          <div style={{ maxWidth: '900px' }}>
205→            {/* Hero Statement - Editorial serif quote style, Pentagram-tight heading */}
206→            <h1
207→              style={{
208→                color: '#a0a0a0',
209→                fontFamily: 'var(--font-lora)',
210→                fontWeight: 400,
211→                fontStyle: 'italic',
212→                fontSize: 'clamp(22px, 3.5vw, 38px)',
213→                lineHeight: 1.2,
214→                letterSpacing: '0.005em',
215→                opacity: introVisible ? 1 : 0,
216→                transform: introVisible ? 'translateY(0)' : `translateY(${isMobile ? 20 : 30}px)`,
217→                transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1), transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1)'
218→              }}
219→            >
220→              {heroStatement}
221→            </h1>
222→          </div>
223→        </section>
224→
225→        {/* Ladder Grid - Golden ratio spacing (excludes hero reel to avoid duplication) */}
226→        <section
227→          className="mx-auto"
228→          style={{
229→            maxWidth: 'var(--max-content-width)',
230→            paddingLeft: 'var(--side-padding)',
231→            paddingRight: 'var(--side-padding)',
232→            paddingBottom: 'var(--space-lg)'    /* 89px - Fibonacci */
233→          }}
234→        >
235→          <LadderGrid projects={adaptedProjects} />
236→        </section>
237→      </main>
238→    </>
239→  );
240→}
