  3→import { useState, useEffect, useRef, useCallback } from 'react';
  4→import { ChatTypingIndicator } from './ChatTypingIndicator';
  5→import { ChatProjectCard, parseMessageWithProjects } from './ChatProjectCard';
  6→import { usePerception, SensorEventType } from '@/lib/perception/context';
