 94→export function ChatBot({ isOpen, onClose }: ChatBotProps) {
 95→  // Get visitor archetype and event recorder from perception system
 96→  const { archetype, confidence, recordEvent, awarenessMode } = usePerception();
 97→
 98→  // Initial greeting changes based on awareness mode
 99→  const getInitialMessage = (): string => {
100→    if (awarenessMode) {
101→      return "You've found the perception layer. This chat adapts to how you browse—faster responses for quick scanners, deeper dives for technical explorers. What would you like to know?";
102→    }
103→    return "What would you like to know about Joseph's work?";
104→  };
105→
106→  const [messages, setMessages] = useState<Message[]>([
107→    { type: 'bot', text: getInitialMessage() }
108→  ]);
109→  const [inputValue, setInputValue] = useState('');
110→  const [isTyping, setIsTyping] = useState(false);
111→  const [hasConversation, setHasConversation] = useState(false);
112→
113→  // Track timing for response read time calculation
114→  const lastBotResponseTimeRef = useRef<number>(0);
115→  const userMessageCountRef = useRef<number>(0);
116→
117→  const inputRef = useRef<HTMLInputElement>(null);
118→  const messagesEndRef = useRef<HTMLDivElement>(null);
119→  const isMountedRef = useRef(true);
120→  const abortControllerRef = useRef<AbortController | null>(null);
121→
122→  // Track mounted state
123→  useEffect(() => {
124→    isMountedRef.current = true;
125→    return () => {
126→      isMountedRef.current = false;
127→      if (abortControllerRef.current) {
128→        abortControllerRef.current.abort();
129→      }
130→    };
131→  }, []);
132→
133→  // Focus input when chatbot opens
134→  useEffect(() => {
135→    if (isOpen && inputRef.current) {
136→      const focusTimeout = setTimeout(() => {
137→        if (isMountedRef.current && inputRef.current) {
138→          inputRef.current.focus();
139→        }
140→      }, 100);
141→      return () => clearTimeout(focusTimeout);
142→    }
143→  }, [isOpen]);
144→
145→  // Scroll to bottom when new messages arrive
146→  useEffect(() => {
147→    if (messagesEndRef.current) {
148→      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
149→    }
150→  }, [messages, isTyping]);
151→
152→  // Handle escape key to close
153→  useEffect(() => {
154→    const handleEscape = (e: KeyboardEvent) => {
155→      if (e.key === 'Escape' && isOpen) {
156→        onClose();
157→      }
158→    };
159→    document.addEventListener('keydown', handleEscape);
160→    return () => document.removeEventListener('keydown', handleEscape);
161→  }, [isOpen, onClose]);
162→
163→  // Reset on open
164→  useEffect(() => {
165→    if (isOpen) {
166→      setMessages([{ type: 'bot', text: getInitialMessage() }]);
167→      setInputValue('');
168→      setIsTyping(false);
169→      setHasConversation(false);
170→      // Reset chat tracking for perception system
171→      lastBotResponseTimeRef.current = 0;
172→      userMessageCountRef.current = 0;
173→      if (abortControllerRef.current) {
174→        abortControllerRef.current.abort();
175→        abortControllerRef.current = null;
176→      }
177→      document.body.setAttribute('data-chatbot-open', 'true');
178→    } else {
179→      document.body.removeAttribute('data-chatbot-open');
180→    }
181→  }, [isOpen, awarenessMode]);
182→
183→  // Send message to AI and stream response
184→  const sendMessage = useCallback(async (query: string) => {
185→    if (!query.trim() || isTyping) return;
186→
187→    // Record response read time if this isn't the first message
188→    if (lastBotResponseTimeRef.current > 0) {
189→      const responseReadTime = Date.now() - lastBotResponseTimeRef.current;
190→      recordEvent({
191→        timestamp: Date.now(),
192→        type: SensorEventType.CHAT_RESPONSE_READ,
193→        data: {
194→          responseReadTime,
195→        },
196→      });
197→    }
198→
199→    // Analyze the message for behavioral signals
200→    const isFollowUp = userMessageCountRef.current > 0;
201→    const messageAnalysis = analyzeChatMessage(query, isFollowUp);
202→    userMessageCountRef.current++;
203→
204→    // Record the chat message event
205→    recordEvent({
206→      timestamp: Date.now(),
207→      type: SensorEventType.CHAT_MESSAGE,
208→      data: {
209→        messageLength: messageAnalysis.messageLength,
210→        wordCount: messageAnalysis.wordCount,
211→        hasTechnicalTerms: messageAnalysis.hasTechnicalTerms,
212→        isFollowUp: messageAnalysis.isFollowUp,
213→        questionCategory: messageAnalysis.questionCategory,
214→      },
215→    });
216→
217→    // Add user message
218→    const userMessage: Message = { type: 'user', text: query };
219→    setMessages(prev => [...prev, userMessage]);
220→    setInputValue('');
221→    setIsTyping(true);
222→    setHasConversation(true);
223→
224→    // Abort any existing request
225→    if (abortControllerRef.current) {
226→      abortControllerRef.current.abort();
227→    }
228→    abortControllerRef.current = new AbortController();
229→
230→    try {
231→      // Get conversation history (excluding the message we just added)
232→      const conversationHistory = messages.map(m => ({
233→        type: m.type,
234→        text: m.text
235→      }));
236→
237→      // Server handles model selection deterministically based on environment
238→      // (Anthropic in production, Ollama locally)
239→      // Visitor context enables archetype-aware response adaptation
240→      const response = await fetch('/api/ai-chat', {
241→        method: 'POST',
242→        headers: { 'Content-Type': 'application/json' },
243→        body: JSON.stringify({
244→          message: query,
245→          messages: conversationHistory,
246→          stream: true,
247→          context: 'portfolio',
248→          // Perception context for invisible adaptation
249→          visitor: {
250→            archetype: archetype ?? 'unknown',
251→            confidence: confidence ?? 0,
252→          },
253→        }),
254→        signal: abortControllerRef.current.signal
255→      });
256→
257→      if (!response.ok) {
258→        throw new Error(`API error: ${response.status}`);
259→      }
260→
261→      // Add empty bot message that we'll stream into
262→      const botMessageIndex = messages.length + 1; // +1 for user message we just added
263→      setMessages(prev => [...prev, { type: 'bot', text: '', isStreaming: true }]);
264→
265→      // Stream the response
266→      const reader = response.body?.getReader();
267→      if (!reader) throw new Error('No response body');
268→
269→      const decoder = new TextDecoder();
270→      let fullText = '';
271→
272→      while (true) {
273→        const { done, value } = await reader.read();
274→        if (done) break;
275→
276→        const chunk = decoder.decode(value, { stream: true });
277→        fullText += chunk;
278→
279→        // Update the bot message with streamed content
280→        if (isMountedRef.current) {
281→          setMessages(prev => {
282→            const updated = [...prev];
283→            const lastIndex = updated.length - 1;
284→            if (updated[lastIndex]?.type === 'bot') {
285→              updated[lastIndex] = { type: 'bot', text: fullText, isStreaming: true };
286→            }
287→            return updated;
288→          });
289→        }
290→      }
291→
292→      // Mark streaming as complete
293→      if (isMountedRef.current) {
294→        setMessages(prev => {
295→          const updated = [...prev];
296→          const lastIndex = updated.length - 1;
297→          if (updated[lastIndex]?.type === 'bot') {
298→            updated[lastIndex] = { type: 'bot', text: fullText, isStreaming: false };
299→          }
300→          return updated;
301→        });
302→        setIsTyping(false);
303→        // Track when bot response completed (for read time calculation)
304→        lastBotResponseTimeRef.current = Date.now();
305→      }
306→
307→    } catch (error) {
308→      if (error instanceof Error && error.name === 'AbortError') {
309→        // Request was aborted, ignore
310→        return;
311→      }
312→
313→      console.error('Chat error:', error);
314→
315→      // Add fallback error message
316→      if (isMountedRef.current) {
317→        setMessages(prev => [...prev, {
318→          type: 'bot',
319→          text: "I'm having trouble connecting right now. You can reach Joseph directly at jomar.ibrahim@gmail.com for any questions about his work or availability."
320→        }]);
321→        setIsTyping(false);
322→      }
323→    }
324→  }, [messages, isTyping, archetype, confidence, recordEvent]);
325→
326→  // Handle form submit
327→  const handleSubmit = useCallback((e: React.FormEvent) => {
328→    e.preventDefault();
329→    sendMessage(inputValue);
330→  }, [inputValue, sendMessage]);
331→
332→  // Handle quick reply click
333→  const handleQuickReply = useCallback((question: string) => {
334→    if (!isTyping) {
335→      sendMessage(question);
336→    }
337→  }, [isTyping, sendMessage]);
338→
339→  if (!isOpen) return null;
340→
341→  const isInitialState = messages.length === 1 && messages[0].type === 'bot';
342→  const currentSuggestions = hasConversation ? FOLLOW_UP_SUGGESTIONS : INITIAL_SUGGESTIONS;
343→
344→  return (
345→    <div
346→      className="fixed inset-0 flex items-center justify-center"
347→      onClick={onClose}
348→      style={{
349→        backgroundColor: '#141414',
350→        zIndex: 200,
351→        animation: 'chatFadeIn 250ms ease-out'
352→      }}
353→    >
354→      {/* Close button */}
355→      <button
356→        onClick={onClose}
357→        className="absolute top-8 right-8 transition-opacity duration-300"
358→        aria-label="Close"
359→        style={{ opacity: 0.4, zIndex: 10 }}
360→        onMouseEnter={(e) => (e.currentTarget.style.opacity = '1')}
361→        onMouseLeave={(e) => (e.currentTarget.style.opacity = '0.4')}
362→      >
363→        <svg
364→          width="24"
365→          height="24"
366→          viewBox="0 0 24 24"
367→          fill="none"
368→          stroke="currentColor"
369→          strokeWidth="1"
370→          strokeLinecap="round"
371→          style={{ color: 'var(--text-muted)' }}
372→        >
373→          <line x1="18" y1="6" x2="6" y2="18" />
374→          <line x1="6" y1="6" x2="18" y2="18" />
375→        </svg>
376→      </button>
377→
378→      {/* Centered container */}
379→      <div
380→        className="w-full max-w-2xl mx-6 md:mx-8"
381→        onClick={(e) => e.stopPropagation()}
382→        style={{
383→          animation: 'chatSlideUp 350ms cubic-bezier(0.16, 1, 0.3, 1)'
384→        }}
385→      >
386→        {/* Messages area */}
387→        <div
388→          className="overflow-y-auto"
389→          style={{
390→            maxHeight: '60vh',
391→            scrollbarWidth: 'thin',
392→            scrollbarColor: '#2a2a2a transparent'
393→          }}
394→        >
