  1→'use client';
  2→
  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import Player from '@vimeo/player';
  5→
  6→/**
  7→ * HERO REEL - Homepage Autoplay Video
  8→ *
  9→ * Consistency guarantees:
 10→ * 1. Deterministic initialization with timeout (12s max)
 11→ * 2. Clean error handling with fallback to static state
 12→ * 3. Proper cleanup on unmount
 13→ * 4. Scroll-based pause/resume with ref tracking
 14→ * 5. Mobile optimization: static thumbnail only (no video player)
 15→ * 6. Error event listeners for runtime failures
 16→ */
 17→
 18→// Timeout for player initialization (12 seconds - supports slow connections)
 19→const INIT_TIMEOUT_MS = 12000;
 20→
 21→// Mobile detection hook - touch devices OR narrow viewports
 22→// Returns { isMobile, isReady } to prevent video initialization race condition
 23→function useIsMobile(): { isMobile: boolean; isReady: boolean } {
 24→  const [isMobile, setIsMobile] = useState(true); // Default to mobile (safer)
 25→  const [isReady, setIsReady] = useState(false);
 26→
 27→  useEffect(() => {
 28→    const checkMobile = () => {
 29→      const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
 30→      const isNarrowViewport = window.innerWidth < 768;
 31→      setIsMobile(isTouchDevice || isNarrowViewport);
 32→    };
 33→
 34→    checkMobile();
 35→    setIsReady(true); // Now we know for sure
 36→    window.addEventListener('resize', checkMobile);
 37→    return () => window.removeEventListener('resize', checkMobile);
 38→  }, []);
 39→
 40→  return { isMobile, isReady };
 41→}
 42→
 43→interface HeroReelProps {
 44→  videoId: string;
 45→  videoHash?: string;
 46→  startTime?: number;
 47→  thumbnail?: string;
 48→}
 49→
 50→export function HeroReel({ videoId, videoHash, startTime = 0, thumbnail }: HeroReelProps) {
 51→  const containerRef = useRef<HTMLDivElement>(null);
 52→  const playerRef = useRef<Player | null>(null);
 53→  const isReadyRef = useRef(false);
 54→  const scrolledDownRef = useRef(false);
 55→
 56→  const [scrollProgress, setScrollProgress] = useState(0);
 57→  const [heroRevealed, setHeroRevealed] = useState(false);
 58→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
 59→
 60→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 61→
 62→  // Thumbnail URL - use provided thumbnail or fallback to Vimeo vumbnail
 63→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
 64→
 65→  // Hero height based on device
 66→  const heroHeight = isMobile ? '50vh' : '70vh';
 67→
 68→  // Clean destroy of player instance
 69→  const destroyPlayer = useCallback(() => {
 70→    if (playerRef.current) {
 71→      try {
 72→        playerRef.current.destroy();
 73→      } catch {
 74→        // Player may already be destroyed
 75→      }
 76→      playerRef.current = null;
 77→    }
 78→    isReadyRef.current = false;
 79→  }, []);
 80→
 81→  // Check reduced motion preference
 82→  useEffect(() => {
 83→    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
 84→    setPrefersReducedMotion(mediaQuery.matches);
 85→    const handleChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
 86→    mediaQuery.addEventListener('change', handleChange);
 87→    return () => mediaQuery.removeEventListener('change', handleChange);
 88→  }, []);
 89→
 90→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 91→  useEffect(() => {
 92→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 93→    return () => clearTimeout(revealTimer);
 94→  }, []);
 95→
 96→  // Initialize Vimeo player with autoplay (desktop only)
 97→  useEffect(() => {
 98→    // Wait for mobile detection to complete before deciding
 99→    if (!isMobileReady) return;
100→
101→    // Skip player initialization on mobile - use static thumbnail instead
102→    if (isMobile) return;
103→
104→    if (!containerRef.current) return;
105→
106→    const baseConfig = {
107→      muted: true,
108→      loop: true,
109→      autoplay: true,
110→      controls: false,
111→      background: true,
112→      responsive: true,
113→      title: false,
114→      byline: false,
115→      portrait: false,
116→      dnt: true,
117→      playsinline: true,
118→      quality: 'auto',
119→      speed: true,
120→    };
121→
122→    const baseUrl = videoHash
123→      ? `https://vimeo.com/${videoId}/${videoHash}`
124→      : `https://vimeo.com/${videoId}`;
125→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
126→
127→    let isMounted = true;
128→
129→    const initPlayer = async () => {
130→      try {
131→        playerRef.current = new Player(containerRef.current!, {
132→          url: urlWithTime as `https://vimeo.com/${string}`,
133→          ...baseConfig
134→        });
135→
136→        // Race between ready() and timeout
137→        const readyPromise = playerRef.current.ready();
138→        const timeoutPromise = new Promise<never>((_, reject) => {
139→          setTimeout(() => reject(new Error('HeroReel initialization timeout')), INIT_TIMEOUT_MS);
140→        });
141→
142→        await Promise.race([readyPromise, timeoutPromise]);
143→
144→        if (!isMounted) {
145→          destroyPlayer();
146→          return;
147→        }
148→
149→        isReadyRef.current = true;
150→
151→        // Add error event listener for runtime failures
152→        playerRef.current.on('error', (error) => {
153→          console.error('HeroReel: Player error', videoId, error);
154→          // Don't destroy - let video degrade gracefully to thumbnail
155→        });
156→
157→        // Start playback
158→        await playerRef.current.play().catch(() => {
159→          // Autoplay blocked - video will show loading state
160→        });
161→      } catch (err) {
162→        console.error('HeroReel: Player init failed', videoId, err);
163→        destroyPlayer();
164→      }
165→    };
166→
167→    initPlayer();
168→
169→    return () => {
170→      isMounted = false;
171→      destroyPlayer();
172→    };
173→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
174→
175→  // Track scroll for fade and pause/resume
176→  useEffect(() => {
177→    const handleScroll = () => {
178→      const scrollY = window.scrollY;
179→      const viewportHeight = window.innerHeight;
180→      // Use appropriate hero height multiplier based on device
181→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
182→      const introPadding = 160;
183→      const textStartPosition = heroHeightValue + introPadding;
184→      const oneThirdViewport = viewportHeight / 3;
185→      const fadeStartScroll = textStartPosition - oneThirdViewport;
186→
187→      const fadeRange = 200;
188→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
189→      setScrollProgress(progress);
190→
191→      // Pause/resume with ref tracking for consistency (desktop only)
192→      if (!isMobile) {
193→        const hasScrolledDown = scrollY > 10;
194→
195→        if (hasScrolledDown && !scrolledDownRef.current) {
196→          scrolledDownRef.current = true;
197→          if (playerRef.current && isReadyRef.current) {
198→            playerRef.current.pause().catch(() => {});
199→          }
200→        } else if (!hasScrolledDown && scrolledDownRef.current) {
201→          scrolledDownRef.current = false;
202→          if (playerRef.current && isReadyRef.current) {
203→            playerRef.current.play().catch(() => {});
204→          }
205→        }
206→      }
207→    };
208→
209→    // Run immediately to sync initial state
210→    handleScroll();
211→
212→    window.addEventListener('scroll', handleScroll, { passive: true });
213→    return () => window.removeEventListener('scroll', handleScroll);
214→  }, [isMobile]);
215→
216→  const scrollOpacity = 1 - scrollProgress;
217→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
218→  const heroScale = heroRevealed ? 1 : 1.02;
219→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
220→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
221→
222→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
223→  // This ensures scroll-driven fade is perfectly synchronized with navigation
224→  const heroTransition = heroRevealed
225→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
226→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
227→
228→  return (
229→    <div
230→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
231→      style={{
232→        height: heroHeight,
233→        zIndex: 0,
234→        backgroundColor: '#141414'
235→      }}
236→    >
237→      <div
238→        style={{
239→          width: '100%',
240→          height: '100%',
241→          opacity: heroOpacity,
242→          transform: `scale(${heroScale})`,
243→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
244→          transition: heroTransition,
245→          transformOrigin: 'center center',
246→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
247→        }}
248→      >
249→        {isMobile ? (
250→          // Mobile: Static thumbnail only (no video player)
251→          <div
252→            className="absolute inset-0 w-full h-full"
253→            style={{
254→              backgroundImage: `url(${thumbnailUrl})`,
255→              backgroundSize: 'cover',
256→              backgroundPosition: 'center',
257→              backgroundColor: '#141414',
258→              zIndex: 0
259→            }}
260→          />
261→        ) : (
262→          // Desktop: Vimeo player container
263→          <div
264→            ref={containerRef}
265→            className="absolute inset-0 w-full h-full"
266→            style={{
267→              backgroundColor: '#141414',
268→              zIndex: 0
269→            }}
270→          />
271→        )}
272→      </div>
273→    </div>
274→  );
275→}
