  1→'use client';
  2→
  3→/**
  4→ * Perception Context
  5→ * Phase 2: USD Substrate Integration
  6→ *
  7→ * Provides:
  8→ * - Shared perception state across components
  9→ * - Event recording for chat behavior feedback
 10→ * - Archetype and confidence accessors
 11→ */
 12→
 13→import { createContext, useContext, useState, useCallback, useRef, useEffect, ReactNode } from 'react';
 14→import { VisitorClassifier } from './classifier';
 15→import { SensorEvent, SensorEventType, VisitorArchetype } from './types';
 16→import type { PerceptionState } from './types';
 17→
 18→interface PerceptionContextValue {
 19→  perceptionState: PerceptionState | null;
 20→  updatePerceptionState: (state: PerceptionState) => void;
 21→  // Record events from any component (e.g., ChatBot)
 22→  recordEvent: (event: Omit<SensorEvent, 'sessionId'>) => void;
 23→  // Get current session ID
 24→  sessionId: string;
 25→  // Convenience accessors
 26→  archetype: VisitorArchetype | null;
 27→  confidence: number;
 28→  // Stability info for debugging
 29→  stability: {
 30→    consecutiveSameArchetype: number;
 31→    totalClassifications: number;
 32→  } | null;
 33→  // Awareness mode: reveals AI perception layer
 34→  awarenessMode: boolean;
 35→  toggleAwarenessMode: () => void;
 36→}
 37→
 38→const PerceptionContext = createContext<PerceptionContextValue | null>(null);
 39→
 40→export function PerceptionProvider({ children }: { children: ReactNode }) {
 41→  const [perceptionState, setPerceptionState] = useState<PerceptionState | null>(null);
 42→  const [awarenessMode, setAwarenessMode] = useState(false);
 43→  const isHydratedRef = useRef(false);
 44→
 45→  // Shared classifier instance
 46→  const classifierRef = useRef<VisitorClassifier | null>(null);
 47→  const sessionIdRef = useRef<string>('');
 48→
 49→  // Initialize session ID on mount
 50→  if (!sessionIdRef.current) {
 51→    sessionIdRef.current = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
 52→  }
 53→
 54→  // Initialize classifier on mount
 55→  if (!classifierRef.current) {
 56→    classifierRef.current = new VisitorClassifier();
 57→  }
 58→
 59→  // Hydrate awarenessMode from sessionStorage on mount
 60→  useEffect(() => {
 61→    const stored = sessionStorage.getItem('awarenessMode');
 62→    if (stored === 'true') {
 63→      setAwarenessMode(true);
 64→    }
 65→    isHydratedRef.current = true;
 66→  }, []);
 67→
 68→  // Persist awarenessMode to sessionStorage when it changes
 69→  useEffect(() => {
 70→    if (isHydratedRef.current) {
 71→      sessionStorage.setItem('awarenessMode', String(awarenessMode));
 72→    }
 73→  }, [awarenessMode]);
 74→
 75→  const updatePerceptionState = useCallback((state: PerceptionState) => {
 76→    setPerceptionState(state);
 77→  }, []);
 78→
 79→  /**
 80→   * Toggle awareness mode - reveals AI perception layer
 81→   * Triggered by double-clicking the chatbot icon
 82→   */
 83→  const toggleAwarenessMode = useCallback(() => {
 84→    setAwarenessMode(prev => !prev);
 85→  }, []);
 86→
 87→  /**
 88→   * Record an event from any component
 89→   * Used by ChatBot to feed chat behavior back into classification
 90→   */
 91→  const recordEvent = useCallback((eventWithoutSession: Omit<SensorEvent, 'sessionId'>) => {
 92→    if (!classifierRef.current) return;
 93→
 94→    const event: SensorEvent = {
 95→      ...eventWithoutSession,
 96→      sessionId: sessionIdRef.current,
 97→    };
 98→
 99→    classifierRef.current.addEvent(event);
100→
101→    // Re-classify and update state
102→    const profile = classifierRef.current.classify();
103→    const newState: PerceptionState = {
104→      sessionId: sessionIdRef.current,
105→      events: [], // Don't pass full event buffer
106→      profile,
107→      adaptations: {
108→        projectOrder: 'default',
109→        lastAdaptation: Date.now(),
110→      },
111→    };
112→    setPerceptionState(newState);
113→  }, []);
114→
115→  const value: PerceptionContextValue = {
116→    perceptionState,
117→    updatePerceptionState,
118→    recordEvent,
119→    sessionId: sessionIdRef.current,
120→    archetype: perceptionState?.profile.archetype ?? null,
121→    confidence: perceptionState?.profile.confidence ?? 0,
122→    stability: perceptionState?.profile.stability ?? null,
123→    awarenessMode,
124→    toggleAwarenessMode,
125→  };
126→
127→  return (
128→    <PerceptionContext.Provider value={value}>
129→      {children}
130→    </PerceptionContext.Provider>
131→  );
132→}
133→
134→export function usePerception(): PerceptionContextValue {
135→  const context = useContext(PerceptionContext);
136→  if (!context) {
137→    // Return safe defaults if used outside provider
138→    return {
139→      perceptionState: null,
140→      updatePerceptionState: () => {},
141→      recordEvent: () => {},
142→      sessionId: '',
143→      archetype: null,
144→      confidence: 0,
145→      stability: null,
146→      awarenessMode: false,
147→      toggleAwarenessMode: () => {},
148→    };
149→  }
150→  return context;
151→}
